node -e "
const fs = require('fs');
const path = require('path');
const dir = 'e:/Desktop/Projects/ecomGliders/content/config/services';
const required = [
  'slug','breadcrumbLabel','hero','stats','problem','solution','deliverables','results','faq','relatedServices','cta','seo'
];
const files = fs.readdirSync(dir).filter(f => f.endsWith('.json'));
const issues = [];
let ok = 0;
for (const file of files) {
  const full = path.join(dir, file);
  let data;
  try {
    data = JSON.parse(fs.readFileSync(full, 'utf8'));
  } catch (e) {
    issues.push(file + ': PARSE ERROR - ' + e.message);
    continue;
  }
  for (const key of required) {
    if (!(key in data)) issues.push(file + ': missing key ' + key);
  }
  if (data.stats && data.stats.length !== 4) issues.push(file + ': stats length ' + (data.stats && data.stats.length));
  if (data.problem && (!data.problem.points || data.problem.points.length !== 4)) issues.push(file + ': problem.points length ' + (data.problem.points && data.problem.points.length));
  if (data.solution && (!data.solution.steps || data.solution.steps.length !== 4)) issues.push(file + ': solution.steps length ' + (data.solution.steps && data.solution.steps.length));
  if (data.deliverables && data.deliverables.items) {
    const n = data.deliverables.items.length;
    if (n < 6 || n > 8) issues.push(file + ': deliverables.items length ' + n);
  }
  if (data.results && (!data.results.items || data.results.items.length !== 2)) issues.push(file + ': results.items length ' + (data.results.items && data.results.items.length));
  if (data.faq && (data.faq.length < 5 || data.faq.length > 6)) issues.push(file + ': faq length ' + data.faq.length);
  if (data.relatedServices && data.relatedServices.length !== 3) issues.push(file + ': relatedServices length ' + data.relatedServices.length);
  if (data.cta && data.cta.button) {
    if (data.cta.button.label !== 'Request a free audit') issues.push(file + ': cta button label mismatch');
    if (data.cta.button.href !== '/free-audit-2/') issues.push(file + ': cta button href mismatch');
  }
  if (data.seo) {
    const expectedCanon = 'https://ecomgliders.com/' + data.slug + '/';
    if (data.seo.canonical !== expectedCanon) issues.push(file + ': canonical mismatch ' + data.seo.canonical);
    if (data.seo.schema !== 'Service') issues.push(file + ': schema not Service');
    if (!data.seo.robots || data.seo.robots.index !== true || data.seo.robots.follow !== true) issues.push(file + ': robots not index/follow');
  }
  if (data.slug + '.json' !== file) issues.push(file + ': slug/file mismatch slug=' + data.slug);
  ok++;
  console.log('OK parse: ' + file);
}
console.log('\\nParsed ' + ok + '/' + files.length + ' files');
if (issues.length) {
  console.log('ISSUES:');
  issues.forEach(i => console.log(' - ' + i));
  process.exit(1);
} else {
  console.log('No structural issues found.');
}
"
